SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM boss_battles
WHERE guild_id = #{guildId}
  AND season_id = #{seasonId}

SELECT 
FROM boss_battles bb
JOIN guilds g ON g.guild_id = bb.guild_id
JOIN bosses b ON b.boss_id = bb.boss_id
JOIN boss_seasons s ON s.season_id = bb.season_id
WHERE bb.guild_id = #{guildId}
ORDER BY bb.started_at DESC, bb.battle_id DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(1)
FROM boss_battles
WHERE guild_id = #{guildId}

SELECT guild_id
FROM boss_battles
WHERE battle_id = #{battleId}
